/**
 * 平台共享系统文本字典 — 4 语 (zh / en / ms / vi).
 *
 * 由平台维护, 不暴露给租户编辑. 租户业务内容 (FAQ / 公司资讯) 走 Task C 草稿流程.
 *
 * 命名约定:
 *   common.*    通用按钮 / 状态 / 表单 label
 *   nav.*       侧边栏导航
 *   page.*      各页面标题
 *   task.*      任务相关
 *   campaign.*  广告投放相关
 *   cs.*        智能客服相关
 *   error.*     Auto-Recovery 错误分类
 *   settings.*  设置 / 语言
 */

